#!/bin/bash
echo "🔥 Building Kids Levels 6-11..."

# Level 6 - Boss Fight: معركة PHANTOM
cat > levels/level6-kids.html << 'EOF'
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Level 6: معركة PHANTOM</title><link rel="stylesheet" href="../css/cyber-theme.css"><style>.boss-area{text-align:center;margin:30px 0}.boss{font-size:8rem;animation:bossFloat 1s infinite;cursor:pointer}@keyframes bossFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-20px)}}.boss-health{width:300px;height:30px;background:#333;border-radius:15px;margin:20px auto;overflow:hidden}.boss-health-fill{width:100%;height:100%;background:red;transition:width 0.5s}.attack-btn{background:red;color:#fff;padding:20px 40px;font-size:1.5rem;border:none;border-radius:15px;cursor:pointer;animation:pulse 0.5s infinite}.attack-btn:active{transform:scale(0.9)}@keyframes pulse{0%,100%{box-shadow:0 0 20px red}50%{box-shadow:0 0 60px red}}.code-attack{background:#000;color:#0f0;padding:15px;border-radius:10px;font-family:monospace;margin:10px;display:inline-block}.xp-earned{font-size:3rem;color:#ffd700;animation:popIn 0.5s}@keyframes popIn{0%{transform:scale(0)}100%{transform:scale(1)}}</style></head><body><canvas id="matrix-canvas"></canvas><div class="cyber-container"><header class="cyber-header"><h1 class="cyber-logo">🐉 LEVEL 6</h1><p class="cyber-subtitle">المعركة النهائية - Boss Fight!</p></header><div class="cyber-section"><h2 style="color:#ff4444;text-align:center">⚡ PHANTOM ينتظرك!</h2><p style="text-align:center;font-size:1.2rem">🤖 <strong>Agent Zero:</strong> "استخدم كل ما تعلمته!<br>اكتب الأكواد الصحيحة لتهزم PHANTOM!"</p></div><div class="cyber-section"><div class="boss-area"><div class="boss" id="boss">👾</div><p style="color:red;font-size:1.5rem">PHANTOM - مستوى 99</p><div class="boss-health"><div class="boss-health-fill" id="boss-health-fill"></div></div><p style="color:#ffd700">صحة: <span id="boss-hp">100</span>/100</p></div><div id="attack-area"><p style="text-align:center;color:#ffd700">اختر الهجوم الصحيح:</p><div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center"><div class="code-attack" data-answer="print" data-damage="25"><code>???("هجوم!")</code><br><small>أكمل الكود</small></div><div class="code-attack" data-answer="for" data-damage="25"><code>??? i in range(3):</code><br><small>أكمل الكود</small></div><div class="code-attack" data-answer="if" data-damage="25"><code>??? boss == "ضعيف":</code><br><small>أكمل الكود</small></div><div class="code-attack" data-answer="def" data-damage="25"><code>??? attack():</code><br><small>أكمل الكود</small></div></div><input type="text" id="answer-input" placeholder="اكتب الكلمة الناقصة..." style="display:block;margin:20px auto;padding:15px;font-size:1.2rem;background:#000;color:#0f0;border:2px solid #0f0;border-radius:10px;width:80%;text-align:center"></div></div><div class="cyber-section" id="mission-complete" style="display:none;text-align:center"><div style="font-size:5rem">🏆</div><h2 style="color:#ffd700">هزمت PHANTOM!</h2><div class="xp-earned">+500 XP</div><p>أنت الآن هاكر محترف!</p><button class="cyber-btn primary" onclick="nextLevel(7)">➡️ المستوى التالي: قطار البيانات</button></div><div style="text-align:center;margin:30px 0"><a href="../index.html" class="cyber-btn">⬅️ العودة للخريطة</a></div></div><script>let hp=100;let currentTarget=null;document.querySelectorAll('.code-attack').forEach(att=>{att.addEventListener('click',function(){currentTarget=this;document.querySelectorAll('.code-attack').forEach(a=>a.style.border='2px solid #0f0');this.style.border='3px solid #ffd700';this.style.boxShadow='0 0 20px #ffd700'})});document.getElementById('answer-input').addEventListener('keypress',function(e){if(e.key==='Enter'&&currentTarget){if(this.value.trim().toLowerCase()===currentTarget.dataset.answer){hp-=parseInt(currentTarget.dataset.damage);document.getElementById('boss-hp').textContent=Math.max(0,hp);document.getElementById('boss-health-fill').style.width=hp+'%';document.getElementById('boss').style.transform='scale(0.8)';setTimeout(()=>document.getElementById('boss').style.transform='scale(1)',200);currentTarget.style.opacity='0.5';currentTarget.style.pointerEvents='none';this.value='';if(hp<=0){document.getElementById('mission-complete').style.display='block';document.getElementById('boss').textContent='💀';if(window.SaveSystem)SaveSystem.save(6,{xp:500})}}else{this.style.borderColor='red';setTimeout(()=>this.style.borderColor='#0f0',500)}}});function nextLevel(n){localStorage.setItem('cyberRPG_level',n);window.location.href='level'+n+'.html'}</script><script src="../js/save-system.js"></script></body></html>
EOF
echo "✅ Level 6 Kids created"

# Level 7 - Lists: قطار البيانات
cat > levels/level7-kids.html << 'EOF'
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Level 7: قطار البيانات</title><link rel="stylesheet" href="../css/cyber-theme.css"><style>.train{display:flex;gap:5px;justify-content:center;margin:30px 0;flex-wrap:wrap}.train-car{background:rgba(0,0,0,0.5);border:3px solid #00ff41;border-radius:15px;padding:20px;min-width:80px;text-align:center;font-size:2rem;transition:all 0.3s}.train-car:hover{border-color:#ffd700;transform:translateY(-10px)}.data-items{display:flex;gap:15px;justify-content:center;flex-wrap:wrap;margin:20px 0}.data-item{background:#ffd700;color:#000;padding:15px;border-radius:10px;cursor:grab;font-weight:bold;font-size:1.2rem}.data-item:active{cursor:grabbing}.code-display{background:#000;color:#0f0;padding:20px;border-radius:10px;font-family:monospace;text-align:center;font-size:1.3rem}</style></head><body><canvas id="matrix-canvas"></canvas><div class="cyber-container"><header class="cyber-header"><h1 class="cyber-logo">🚂 LEVEL 7</h1><p class="cyber-subtitle">قطار البيانات - Lists</p></header><div class="cyber-section"><h2 style="color:#ff4444;text-align:center">📦 رتب البيانات!</h2><p style="text-align:center;font-size:1.2rem">🤖 <strong>Agent Zero:</strong> "القائمة = قطار!<br>كل عربة تحمل بيانات. رتبها بالترتيب الصحيح!"</p></div><div class="cyber-section"><h2 style="text-align:center">🚂 قطار البيانات</h2><div class="train" id="train"><div class="train-car">🚂</div><div class="train-car" id="car-0">⬜</div><div class="train-car" id="car-1">⬜</div><div class="train-car" id="car-2">⬜</div></div><div class="data-items"><div class="data-item" draggable="true" data-value="تفاح">🍎 تفاح</div><div class="data-item" draggable="true" data-value="موز">🍌 موز</div><div class="data-item" draggable="true" data-value="عنب">🍇 عنب</div></div><div class="code-display"><pre>fruits = ["تفاح", "موز", "عنب"]
print(fruits[0])  # → تفاح
print(fruits[1])  # → موز</pre></div></div><div class="cyber-section" id="mission-complete" style="display:none;text-align:center"><div style="font-size:5rem">🏆</div><h2 style="color:#ffd700">ركبت القطار!</h2><p>List = مجموعة مرتبة من البيانات!</p><button class="cyber-btn primary" onclick="nextLevel(8)">➡️ المستوى التالي</button></div><div style="text-align:center;margin:30px 0"><a href="../index.html" class="cyber-btn">⬅️ العودة للخريطة</a></div></div><script>let filled=0;document.querySelectorAll('.data-item').forEach(item=>{item.addEventListener('dragstart',e=>{e.dataTransfer.setData('text',item.dataset.value)})});document.querySelectorAll('.train-car[id]').forEach(car=>{car.addEventListener('dragover',e=>{e.preventDefault();car.style.borderColor='#ffd700'});car.addEventListener('dragleave',e=>{car.style.borderColor='#00ff41'});car.addEventListener('drop',e=>{e.preventDefault();let val=e.dataTransfer.getData('text');car.textContent=val;car.style.borderColor='#ffd700';car.style.background='rgba(255,215,0,0.2)';filled++;if(filled>=3){document.getElementById('mission-complete').style.display='block';if(window.SaveSystem)SaveSystem.save(7,{xp:100})}})});function nextLevel(n){localStorage.setItem('cyberRPG_level',n);window.location.href='level'+n+'.html'}</script><script src="../js/save-system.js"></script></body></html>
EOF
echo "✅ Level 7 Kids created"

# Level 8 - Files: فتح الخزائن
cat > levels/level8-kids.html << 'EOF'
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Level 8: فتح الخزائن</title><link rel="stylesheet" href="../css/cyber-theme.css"><style>.vaults{display:flex;flex-wrap:wrap;gap:20px;justify-content:center;margin:30px 0}.vault{background:linear-gradient(135deg,#1a1a2e,#0a0a0f);border:3px solid #ffd700;border-radius:20px;padding:30px;text-align:center;cursor:pointer;transition:all 0.3s;font-size:3rem;min-width:120px}.vault:hover{transform:scale(1.1);box-shadow:0 0 30px rgba(255,215,0,0.5)}.vault.opened{background:rgba(0,255,65,0.2);border-color:#00ff41}.vault.locked{cursor:not-allowed;opacity:0.5}.key{background:#ffd700;color:#000;padding:10px 20px;border-radius:10px;cursor:pointer;font-weight:bold;margin:10px}.file-content{background:#000;color:#0f0;padding:20px;border-radius:10px;font-family:monospace;text-align:center;margin-top:20px}</style></head><body><canvas id="matrix-canvas"></canvas><div class="cyber-container"><header class="cyber-header"><h1 class="cyber-logo">📁 LEVEL 8</h1><p class="cyber-subtitle">فتح الخزائن - File Handling</p></header><div class="cyber-section"><h2 style="color:#ff4444;text-align:center">🔐 افتح الخزائن!</h2><p style="text-align:center;font-size:1.2rem">🤖 <strong>Agent Zero:</strong> "الملفات = خزائن!<br>كل خزنة لها مفتاح. استخدم المفتاح الصحيح!"</p></div><div class="cyber-section"><h2 style="text-align:center">🗄️ الخزائن</h2><div class="vaults"><div class="vault locked" data-file="secret.txt" data-key="open">🔒<br>secret.txt</div><div class="vault locked" data-file="password.txt" data-key="read">🔒<br>password.txt</div><div class="vault locked" data-file="data.txt" data-key="open">🔒<br>data.txt</div></div><div style="text-align:center"><p style="color:#ffd700">🔑 المفاتيح:</p><div class="key" data-key="open">📖 open()</div><div class="key" data-key="read">📖 read()</div></div><div class="file-content" id="file-content" style="display:none"></div></div><div class="cyber-section" id="mission-complete" style="display:none;text-align:center"><div style="font-size:5rem">🏆</div><h2 style="color:#ffd700">فتحت كل الخزائن!</h2><p>File = نفتحه بـ open() ونقرأه بـ read()!</p><button class="cyber-btn primary" onclick="nextLevel(9)">➡️ المستوى التالي</button></div><div style="text-align:center;margin:30px 0"><a href="../index.html" class="cyber-btn">⬅️ العودة للخريطة</a></div></div><script>let opened=0;let selectedKey=null;document.querySelectorAll('.key').forEach(k=>{k.addEventListener('click',function(){selectedKey=this.dataset.key;document.querySelectorAll('.key').forEach(x=>x.style.background='#ffd700');this.style.background='#00ff41';this.style.color='#000'})});document.querySelectorAll('.vault').forEach(v=>{v.addEventListener('click',function(){if(!selectedKey)return;if(this.dataset.key===selectedKey){this.classList.remove('locked');this.classList.add('opened');this.textContent='📂\\n'+this.dataset.file;document.getElementById('file-content').style.display='block';document.getElementById('file-content').textContent='📄 محتوى '+this.dataset.file+': [بيانات سرية!]';opened++;if(opened>=3){document.getElementById('mission-complete').style.display='block';if(window.SaveSystem)SaveSystem.save(8,{xp:100})}}else{this.style.borderColor='red';setTimeout(()=>this.style.borderColor='#ffd700',500)}})}});function nextLevel(n){localStorage.setItem('cyberRPG_level',n);window.location.href='level'+n+'.html'}</script><script src="../js/save-system.js"></script></body></html>
EOF
echo "✅ Level 8 Kids created"

# Level 9 - Regex: عدسة مكبرة
cat > levels/level9-kids.html << 'EOF'
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Level 9: عدسة مكبرة</title><link rel="stylesheet" href="../css/cyber-theme.css"><style>.text-area{background:#000;color:#0f0;padding:30px;border-radius:15px;font-family:monospace;font-size:1.3rem;line-height:2;text-align:center;margin:20px 0}.highlight{background:#ffd700;color:#000;padding:2px 8px;border-radius:5px}.magnifier{font-size:5rem;text-align:center;animation:float 2s infinite}@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}.pattern-btn{background:rgba(0,0,0,0.5);border:2px solid #00ff41;color:#fff;padding:15px 25px;border-radius:10px;cursor:pointer;font-size:1.1rem;margin:10px;transition:all 0.3s}.pattern-btn:hover{border-color:#ffd700;background:rgba(255,215,0,0.2)}.pattern-btn.found{background:rgba(0,255,65,0.3);border-color:#00ff41}</style></head><body><canvas id="matrix-canvas"></canvas><div class="cyber-container"><header class="cyber-header"><h1 class="cyber-logo">🔍 LEVEL 9</h1><p class="cyber-subtitle">عدسة مكبرة - Regex</p></header><div class="cyber-section"><h2 style="color:#ff4444;text-align:center">🔎 جد الأنماط المخفية!</h2><p style="text-align:center;font-size:1.2rem">🤖 <strong>Agent Zero:</strong> "Regex = عدسة مكبرة!<br>تجد الكلمات المتشابهة في النص!"</p></div><div class="cyber-section"><div class="magnifier">🔍</div><div class="text-area" id="text-area">البريد: agent@cyber.com<br>الهاتف: 055-123-4567<br>الرمز: ABC-999-XYZ<br>بريد آخر: admin@cyber.com</div><p style="text-align:center;color:#ffd700">🎯 جد الأنماط:</p><div style="text-align:center"><button class="pattern-btn" data-pattern="البريد">📧 ايميلات</button><button class="pattern-btn" data-pattern="الهاتف">📱 أرقام هواتف</button><button class="pattern-btn" data-pattern="الرمز">🔑 رموز</button></div></div><div class="cyber-section" id="mission-complete" style="display:none;text-align:center"><div style="font-size:5rem">🏆</div><h2 style="color:#ffd700">وجدت كل الأنماط!</h2><p>Regex = طريقة ذكية للبحث عن أنماط في النص!</p><button class="cyber-btn primary" onclick="nextLevel(10)">➡️ المستوى التالي</button></div><div style="text-align:center;margin:30px 0"><a href="../index.html" class="cyber-btn">⬅️ العودة للخريطة</a></div></div><script>let found=0;document.querySelectorAll('.pattern-btn').forEach(btn=>{btn.addEventListener('click',function(){if(!this.classList.contains('found')){this.classList.add('found');this.textContent+=' ✅';found++;if(found>=3){document.getElementById('mission-complete').style.display='block';if(window.SaveSystem)SaveSystem.save(9,{xp:100})}}})});function nextLevel(n){localStorage.setItem('cyberRPG_level',n);window.location.href='level'+n+'.html'}</script><script src="../js/save-system.js"></script></body></html>
EOF
echo "✅ Level 9 Kids created"

# Level 10 - APIs: إشارات لاسلكية
cat > levels/level10-kids.html << 'EOF'
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Level 10: إشارات لاسلكية</title><link rel="stylesheet" href="../css/cyber-theme.css"><style>.signal-tower{text-align:center;font-size:6rem;animation:pulse 1.5s infinite}@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.5}}.signal-wave{width:200px;height:200px;border-radius:50%;border:3px solid #00ff41;margin:20px auto;animation:expand 2s infinite}@keyframes expand{0%{transform:scale(0.5);opacity:1}100%{transform:scale(1.5);opacity:0}}.api-request{background:#000;color:#0f0;padding:20px;border-radius:10px;font-family:monospace;text-align:center;margin:10px;cursor:pointer;transition:all 0.3s}.api-request:hover{border-color:#ffd700;box-shadow:0 0 20px rgba(255,215,0,0.5)}.response{background:rgba(0,255,65,0.1);padding:15px;border-radius:10px;margin-top:10px;display:none}</style></head><body><canvas id="matrix-canvas"></canvas><div class="cyber-container"><header class="cyber-header"><h1 class="cyber-logo">📡 LEVEL 10</h1><p class="cyber-subtitle">إشارات لاسلكية - APIs</p></header><div class="cyber-section"><h2 style="color:#ff4444;text-align:center">📡 أرسل إشارات للخادم!</h2><p style="text-align:center;font-size:1.2rem">🤖 <strong>Agent Zero:</strong> "API = إشارة لاسلكية!<br>ترسل طلب → يرجع لك رد!"</p></div><div class="cyber-section"><div class="signal-tower">📡</div><div class="signal-wave"></div><p style="text-align:center;color:#ffd700">🎯 اضغط على الطلبات:</p><div class="api-request" data-endpoint="/get-user"><strong>GET /get-user</strong><br>📥 اجلب بيانات المستخدم<div class="response">✅ رد: { "name": "Agent Cyber", "level": 99 }</div></div><div class="api-request" data-endpoint="/get-mission"><strong>GET /get-mission</strong><br>📥 اجلب المهمة الحالية<div class="response">✅ رد: { "mission": "اختراق الخادم الرئيسي" }</div></div><div class="api-request" data-endpoint="/get-secret"><strong>GET /get-secret</strong><br>📥 اجلب السر المخفي<div class="response">✅ رد: { "secret": "PHANTOM_DEFEATED" }</div></div></div><div class="cyber-section" id="mission-complete" style="display:none;text-align:center"><div style="font-size:5rem">🏆</div><h2 style="color:#ffd700">فهمت APIs!</h2><p>API = ترسل طلب → تستقبل رد!</p><button class="cyber-btn primary" onclick="nextLevel(11)">➡️ المستوى الأخير</button></div><div style="text-align:center;margin:30px 0"><a href="../index.html" class="cyber-btn">⬅️ العودة للخريطة</a></div></div><script>let completed=0;document.querySelectorAll('.api-request').forEach(req=>{req.addEventListener('click',function(){let resp=this.querySelector('.response');if(resp.style.display!=='block'){resp.style.display='block';this.style.borderColor='#00ff41';completed++;if(completed>=3){document.getElementById('mission-complete').style.display='block';if(window.SaveSystem)SaveSystem.save(10,{xp:100})}}})});function nextLevel(n){localStorage.setItem('cyberRPG_level',n);window.location.href='level'+n+'.html'}</script><script src="../js/save-system.js"></script></body></html>
EOF
echo "✅ Level 10 Kids created"

# Level 11 - Scraping: شبكة عنكبوت
cat > levels/level11-kids.html << 'EOF'
<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Level 11: شبكة عنكبوت</title><link rel="stylesheet" href="../css/cyber-theme.css"><style>.web{position:relative;width:300px;height:300px;margin:30px auto}.web-center{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:4rem}.web-node{position:absolute;background:rgba(0,255,65,0.2);border:2px solid #00ff41;border-radius:50%;padding:10px;cursor:pointer;transition:all 0.3s;font-size:1.5rem}.web-node:hover{background:rgba(255,215,0,0.3);border-color:#ffd700;transform:scale(1.3)}.web-node.collected{background:rgba(0,255,65,0.5);border-color:#ffd700}.data-collected{text-align:center;font-size:1.3rem;color:#ffd700;margin-top:20px}</style></head><body><canvas id="matrix-canvas"></canvas><div class="cyber-container"><header class="cyber-header"><h1 class="cyber-logo">🕷️ LEVEL 11</h1><p class="cyber-subtitle">شبكة عنكبوت - Web Scraping</p></header><div class="cyber-section"><h2 style="color:#ff4444;text-align:center">🕸️ اجمع البيانات من الويب!</h2><p style="text-align:center;font-size:1.2rem">🤖 <strong>Agent Zero:</strong> "Web Scraping = شبكة عنكبوت!<br>تجمع البيانات من المواقع!"</p></div><div class="cyber-section"><h2 style="text-align:center">🕸️ شبكة البيانات</h2><div class="web"><div class="web-center">🕷️</div><div class="web-node" style="top:10%;left:50%" data-info="اسم المستخدم: Admin">👤</div><div class="web-node" style="top:30%;left:20%" data-info="بريد: admin@cyber.com">📧</div><div class="web-node" style="top:30%;left:80%" data-info="كلمة سر: ****">🔑</div><div class="web-node" style="top:60%;left:30%" data-info="منفذ: 8080">🚪</div><div class="web-node" style="top:60%;left:70%" data-info="خادم: Apache">🖥️</div><div class="web-node" style="top:80%;left:50%" data-info="دولة: CyberLand">🌍</div></div><div class="data-collected" id="data-collected">البيانات المجمعة: 0/6</div></div><div class="cyber-section" id="mission-complete" style="display:none;text-align:center"><div style="font-size:5rem">🏆</div><h2 style="color:#ffd700">جمعت كل البيانات!</h2><p>Web Scraping = استخراج البيانات من صفحات الويب!</p><button class="cyber-btn primary" onclick="completeGame()">🎉 إنهاء اللعبة!</button></div><div style="text-align:center;margin:30px 0"><a href="../index.html" class="cyber-btn">⬅️ العودة للخريطة</a></div></div><script>let collected=0;document.querySelectorAll('.web-node').forEach(node=>{node.addEventListener('click',function(){if(!this.classList.contains('collected')){this.classList.add('collected');this.textContent='✅';collected++;document.getElementById('data-collected').textContent='البيانات المجمعة: '+collected+'/6';if(collected>=6){document.getElementById('mission-complete').style.display='block';if(window.SaveSystem)SaveSystem.save(11,{xp:500})}}})});function completeGame(){localStorage.setItem('cyberRPG_completed','true');localStorage.setItem('cyberRPG_date',new Date().toLocaleString());window.location.href='../index.html'}</script><script src="../js/save-system.js"></script></body></html>
EOF
echo "✅ Level 11 Kids created"

echo "🎉 All Kids Levels (6-11) created!"
